"use strict";
const crypto=require("node:crypto"),fs=require("node:fs"),path=require("node:path");
const {validatePointerBundle}=require("./publication-validation");
const ID=/^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/u;
const digest=b=>crypto.createHash("sha256").update(b).digest("hex");
const atomic=(file,value)=>{const tmp=`${file}.${process.pid}.${crypto.randomUUID()}.tmp`;const fd=fs.openSync(tmp,"wx",0o640);try{fs.writeSync(fd,`${JSON.stringify(value,null,2)}\n`);if(typeof fs.fsyncSync==="function")fs.fsyncSync(fd);}finally{fs.closeSync(fd);}fs.renameSync(tmp,file);};
function validId(id){if(typeof id!=="string"||!ID.test(id)||id.normalize("NFC")!==id)throw Error("INVALID_GENERATION_ID");return id;}
function guardRoot(root){if(fs.existsSync(root)){const st=fs.lstatSync(root);if(st.isSymbolicLink()||!st.isDirectory()||fs.readdirSync(root).length)throw Error("OUTPUT_ROOT_EXISTS_OR_UNSAFE");}else fs.mkdirSync(root,{recursive:true,mode:0o750});}
async function copyHash(source,target){const input=fs.createReadStream(source,{highWaterMark:1024*1024}),fd=fs.openSync(target,"wx",0o640),h=crypto.createHash("sha256");let size=0;try{for await(const chunk of input){fs.writeSync(fd,chunk);h.update(chunk);size+=chunk.length;}}finally{fs.closeSync(fd);input.destroy();}return {sha256:h.digest("hex"),size};}
async function buildBundle(o){validId(o.publicationId);validId(o.generationId);validId(o.rollbackGenerationId);if(o.generationId===o.rollbackGenerationId)throw Error("ROLLBACK_ID_REUSED");for(const file of [o.sourceJsonl,o.sourceManifest])if(!fs.existsSync(file)||fs.lstatSync(file).isSymbolicLink())throw Error("SOURCE_ARTIFACT_UNSAFE");const source=JSON.parse(fs.readFileSync(o.sourceManifest,"utf8"));if(source.schema_version!==1||source.export_complete!==true||source.publication_performed!==false||source.reconciliation_safe!==false)throw Error("SOURCE_MANIFEST_INVALID");guardRoot(o.outputRoot);const started=new Date().toISOString(),generations=path.join(o.outputRoot,"generations");fs.mkdirSync(generations,{mode:0o750});
  const make=async id=>{const dir=path.join(generations,validId(id));if(fs.existsSync(dir))throw Error("GENERATION_ALREADY_EXISTS");fs.mkdirSync(dir,{mode:0o750});const payload=await copyHash(o.sourceJsonl,path.join(dir,"catalog.jsonl"));const manifest={schema:"webshare-catalog-publication/v1",schema_version:1,publication_id:o.publicationId,generation_id:id,created_at:started,generated_at:started,source_kind:"sqlite-export",source_jsonl_sha256:source.jsonl_sha256,generation_jsonl_sha256:payload.sha256,jsonl_sha256:payload.sha256,jsonl_size_bytes:payload.size,record_count:source.exported_row_count,exported_row_count:source.exported_row_count,source_database_digest:source.source_database_digest,source_database_row_count:source.source_row_count,record_schema:"catalog-record/v1",ordering_contract:source.ordering_contract,active_only:true,scope:"active files",export_complete:true,enumeration_complete:false,immutable_generation:true,publication_performed:false,activation_performed:false,reconciliation_safe:false,builder_commit:o.builderCommit||"unknown",builder_version:"b30a-1",jsonl_filename:"catalog.jsonl",manifest_filename:"publication.manifest.json"};const manifestPath=path.join(dir,"publication.manifest.json");atomic(manifestPath,manifest);manifest.bundle_digest=digest(fs.readFileSync(manifestPath));atomic(manifestPath,manifest);return {dir,payload,manifestPath};};
  const candidate=await make(o.generationId),rollback=await make(o.rollbackGenerationId);const pointer={schema:"webshare-catalog-current/v1",schema_version:1,publication_id:o.publicationId,generation_id:o.generationId,generation_path:`generations/${o.generationId}`,manifest_filename:"publication.manifest.json",manifest_sha256:digest(fs.readFileSync(candidate.manifestPath)),created_at:started,activation_performed:false};const pointerPath=path.join(o.outputRoot,"current.json");atomic(pointerPath,pointer);const resolved=validatePointerBundle(o.outputRoot,pointerPath);const rollbackPointer={...pointer,generation_id:o.rollbackGenerationId,generation_path:`generations/${o.rollbackGenerationId}`,manifest_sha256:digest(fs.readFileSync(rollback.manifestPath))};atomic(path.join(o.outputRoot,"rollback-current.json"),rollbackPointer);return {publication_id:o.publicationId,generation_id:o.generationId,rollback_generation_id:o.rollbackGenerationId,current_pointer:pointerPath,current_pointer_sha256:digest(fs.readFileSync(pointerPath)),candidate,rollback,resolved};}
module.exports={validId,buildBundle};
